tool_input.command:
cat > /tmp/test-thresholds.js << 'EOF'
import { runEvaluations, generateReport } from './packages/frai-core/src/eval/index.js';

// Test 1: Passing thresholds
const evaluations1 = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});
const report1 = generateReport({
  evaluations: evaluations1,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});
console.log('Test 1 (passing thresholds):');
console.log('  passed:', report1.passed);
console.log('  thresholds:', report1.thresholds);
console.log('');

// Test 2: Failing thresholds
const evaluations2 = runEvaluations({
  outputs: ['Hello'],
  references: ['world']
});
const report2 = generateReport({
  evaluations: evaluations2,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});
console.log('Test 2 (failing thresholds):');
console.log('  passed:', report2.passed);
console.log('  thresholds:', report2.thresholds);
console.log('');

// Test 3: Metric with no score
const evaluations3 = runEvaluations({
  outputs: ['Hello'],
  references: []
});
const report3 = generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 }
});
console.log('Test 3 (metric with no score):');
console.log('  passed:', report3.passed);
console.log('  thresholds:', report3.thresholds);
console.log('');

// Test 4: No thresholds provided
const evaluations4 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report4 = generateReport({
  evaluations: evaluations4,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});
console.log('Test 4 (no thresholds):');
console.log('  has passed field:', 'passed' in report4);
console.log('  has thresholds field:', 'thresholds' in report4);
EOF
node /tmp/test-thresholds.js
